    except ImportError: print(f'{m}: MISSING')
" 2>&1 | tail -8

.venv/bin/python - <<'PYEOF'
import sys, math; sys.path.insert(0,'scripts')
import model_catalog as mc
cards = {c.model_id: c for c in mc._catalog_cards()}
names = list(mc.BENCHMARKS)
fit = mc.fit_capability(mc._catalog_cards())
lg, sg = mc._logit, mc._sigmoid

print("residuals of the current additive fit (actual - predicted, score points):\n")
for mid, c in cards.items():
    a = fit['models'][mid]['ability']
    if a is None: continue
    parts=[]
    for n in names:
        s = c.score(n)
        if s is None: continue
        pred = 100*sg(a + fit['difficulty'][n])
        parts.append(f"{n[:12]}:{s-pred:+6.1f}")
    print(f"  {mid:<20}{'  '.join(parts)}")

print("\n>>> Sol's SWE-bench Pro is the outlier that sinks it.\n")

# --- prototype: least-squares ranking from pairwise comparisons on SHARED support only
W = {n: mc.BENCHMARKS[n]['weight'] for n in names}
ids = [m for m in cards if any(cards[m].score(n) is not None for n in names)]
pair = {}
for a in ids:
    for b in ids:
        if a >= b: continue
        shared = [n for n in names if cards[a].score(n) is not None and cards[b].score(n) is not None]
        if not shared: continue
        tw = sum(W[n] for n in shared)
        d = sum(W[n]*(lg(cards[a].score(n)) - lg(cards[b].score(n))) for n in shared)/tw
        pair[(a,b)] = (tw, d)

adj = {m: [] for m in ids}
for (a,b),(w,d) in pair.items():
    adj[a].append((b, w,  d))
    adj[b].append((a, w, -d))

abil = {m: 0.0 for m in ids}
for _ in range(20000):
    delta = 0.0
    for m in ids:
        num = sum(w*(abil[o]+d) for o,w,d in adj[m]); den = sum(w for _,w,_ in adj[m])
        if den:
            new = num/den; delta = max(delta, abs(new-abil[m])); abil[m] = new
    mean = sum(abil.values())/len(abil)
    for m in ids: abil[m] -= mean
    if delta < 1e-13: break

print(f"{'model':<20}{'additive':>10}{'pairwise':>10}")
for m in sorted(ids, key=lambda x: -abil[x]):
    print(f"  {m:<18}{fit['models'][m]['expected_score']:>10.2f}{100*sg(abil[m]+1.6):>10.2f}")

v=0
for a in ids:
    for b in ids:
        if a==b: continue
        sh=[n for n in names if cards[a].score(n) is not None and cards[b].score(n) is not None]
        if len(sh)<2: continue
        if all(cards[a].score(n)>=cards[b].score(n) for n in sh) and any(cards[a].score(n)>cards[b].score(n) for n in sh):
            if abil[a] < abil[b]: print(f"  VIOLATION {a} < {b}"); v+=1
print(f"\npairwise dominance violations: {v}")
PYEOF

.venv/bin/python -c "
import json
nb=json.load(open('notebooks/complexity_pipeline.ipynb'))
for i in (12,21):
    s=''.join(nb['cells'][i]['source'])
    print(f'--- cell {i} ({nb[\"cells\"][i][\"cell_type\"]}) ---')
    for line in s.split(chr(10)):
        if 'price' in line.lower() or 'cost' in line.lower(): print('   >', line)
"
